import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { createBook, getBook, updateBook } from './services/booksApi';
import api from '../../services/api';
import Button from '../../components/common/Button';

export default function BookForm() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [authors, setAuthors] = useState([]);
  const [categories, setCategories] = useState([]);
  const [publishers, setPublishers] = useState([]);
  const [coverFile, setCoverFile] = useState(null);
  const [coverPreview, setCoverPreview] = useState('');
  const [form, setForm] = useState({
    title: '', isbn: '', publisher: '', publication_year: '', description: '', authors: [], categories: [],
  });

  const [error, setError] = useState('');

  useEffect(() => {
    api.get('/books/authors/').then(({ data }) => setAuthors(data.results || data));
    api.get('/books/categories/').then(({ data }) => setCategories(data.results || data));
    api.get('/books/publishers/').then(({ data }) => setPublishers(data.results || data));
    if (id) {
      getBook(id).then(({ data }) => {
        setForm({
          ...data,
          publisher: data.publisher?.id || '',
          authors: data.authors?.map((a) => a.id) || [],
          categories: data.categories?.map((c) => c.id) || [],
        });
        setCoverPreview(data.cover || '');
      });
    }
  }, [id]);

  const handleChange = (e) => {
    let value;
    if (e.target.multiple) {
      value = Array.from(e.target.selectedOptions).filter((o) => o.selected).map((o) => Number(o.value));
    } else if (e.target.type === 'checkbox') {
      value = e.target.checked;
    } else {
      value = e.target.value;
    }
    setForm({ ...form, [e.target.name]: value });
  };

  const handleCoverChange = (e) => {
    const file = e.target.files?.[0] || null;
    setCoverFile(file);
    if (file) {
      setCoverPreview(URL.createObjectURL(file));
    } else {
      setCoverPreview('');
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    try {
      const payload = new FormData();
      payload.append('title', form.title || '');
      payload.append('isbn', form.isbn || '');
      if (form.publisher) payload.append('publisher', form.publisher);
      if (form.publication_year) payload.append('publication_year', String(form.publication_year));
      payload.append('description', form.description || '');
      (form.authors || []).forEach((authorId) => payload.append('authors', authorId));
      (form.categories || []).forEach((categoryId) => payload.append('categories', categoryId));
      if (coverFile) payload.append('cover', coverFile);

      if (id) {
        await updateBook(id, payload, { headers: { 'Content-Type': 'multipart/form-data' } });
      } else {
        await createBook(payload, { headers: { 'Content-Type': 'multipart/form-data' } });
      }
      navigate('/books');
    } catch (err) {
      const msg = err.response?.data?.detail || err.response?.data || 'Save failed';
      setError(typeof msg === 'string' ? msg : JSON.stringify(msg));
    }
  };

  return (
    <form onSubmit={handleSubmit} className="book-form">
      <h2>{id ? 'Edit Book' : 'Add Book'}</h2>
      {error && <p className="error">{error}</p>}
      <input name="title" placeholder="Title" value={form.title} onChange={handleChange} required />
      <input name="isbn" placeholder="ISBN" value={form.isbn} onChange={handleChange} />
      <select name="publisher" value={form.publisher} onChange={handleChange}>
        <option value="">Select Publisher</option>
        {publishers.map((p) => <option key={p.id} value={p.id}>{p.name}</option>)}
      </select>
      <input name="publication_year" type="number" placeholder="Year" value={form.publication_year} onChange={handleChange} />
      <select name="authors" multiple value={form.authors} onChange={handleChange}>
        {authors.map((a) => <option key={a.id} value={a.id}>{a.name}</option>)}
      </select>
      <select name="categories" multiple value={form.categories} onChange={handleChange}>
        {categories.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
      </select>
      <textarea name="description" placeholder="Description" value={form.description} onChange={handleChange} />
      <input type="file" accept="image/*" onChange={handleCoverChange} />
      {coverPreview && <img src={coverPreview} alt="Cover preview" style={{ maxWidth: 180, marginTop: 8 }} />}
      <Button type="submit">{id ? 'Update' : 'Create'}</Button>
    </form>
  );
}
